const defaultOptions: Options = {
  zoom: 14,
  api_key: import.meta.env.PUBLIC_GOOGLE_MAPS_API_KEY || ''
};

// Destructure props with defaults
const { 
  locations = defaultLocations, 
  options = {} 
} = Astro.props;

// Merge provided options with defaults
const mergedOptions: Options = {
  ...defaultOptions,
  ...options
};

// Check for API key
